public static int countDoubles(int[] numbers) {
    if (numbers == null || numbers.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : numbers) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int count = 0;
    for (int num : numbers) {
        if (num % 2 != 0) {
            continue;
        }
        int half = num / 2;
        Integer halfCount = freq.get(half);
        if (halfCount == null) {
            continue;
        }
        if (half != num || halfCount > 1) {
            count++;
        }
    }
    return count;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // If start or end arrays are empty, cannot travel
    if (start == null || end == null || start.length == 0 || end.length == 0) {
        return "cannot be travelled";
    }
    int startNode = start[0];
    int endNode = end[0];
    if (startNode == endNode) {
        return "can be travelled";
    }
    // Build adjacency list
    List<List<Integer>> adj = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        adj.add(new ArrayList<>());
    }
    for (int[] edge : paths) {
        if (edge == null || edge.length < 2) continue;
        int u = edge[0];
        int v = edge[1];
        if (u >= 0 && u < n && v >= 0 && v < n) {
            adj.get(u).add(v);
            adj.get(v).add(u);
        }
    }
    // BFS
    boolean[] visited = new boolean[n];
    Queue<Integer> queue = new ArrayDeque<>();
    queue.offer(startNode);
    visited[startNode] = true;
    while (!queue.isEmpty()) {
        int cur = queue.poll();
        for (int nb : adj.get(cur)) {
            if (!visited[nb]) {
                if (nb == endNode) {
                    return "can be travelled";
                }
                visited[nb] = true;
                queue.offer(nb);
            }
        }
    }
    return "cannot be travelled";
}

