public boolean hasAllCodes(String s, int k) {
    int total = 1 << k;
    if (s.length() < total) return false;
    boolean[] seen = new boolean[total];
    int mask = total - 1;
    int curr = 0;
    int count = 0;
    for (int i = 0; i < s.length(); i++) {
        curr = ((curr << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            if (!seen[curr]) {
                seen[curr] = true;
                count++;
                if (count == total) return true;
            }
        }
    }
    return false;
}

