        minSoFar = Math.min(minSoFar, minEnding);
    }
    return Math.max(maxSoFar, -minSoFar);
}

public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k
    int[] fib = new int[50]; // enough for int range
    fib[0] = 1;
    fib[1] = 1;
    int size = 2;
    while (true) {
        int next = fib[size - 1] + fib[size - 2];
        if (next > k) break;
        fib[size++] = next;
    }

    int count = 0;
    int remaining = k;
    for (int i = size - 1; i >= 0 && remaining > 0; i--) {
        if (fib[i] <= remaining) {
            remaining -= fib[i];
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> large = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            if (i != n / i) {
                large.add(n / i);
            }
        }
    }
    java.util.Collections.reverse(large);
    int total = small.size() + large.size();
    if (k > total) return -1;
    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        return large.get(k - small.size() - 1);
    }
}

