public String getSmallestString(int n, int k) {
    // Start with all 'a's
    char[] result = new char[n];
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    // Remaining value to distribute
    int remaining = k - n; // since each 'a' contributes 1
    // Distribute from the end to keep lexicographically smallest
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // max we can add to this position
        result[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(result);
}

