public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low <= 0 && high >= 0) {
        result.add(0);
    }
    Queue<Long> queue = new LinkedList<>();
    for (int d = 1; d <= 9; d++) {
        if (d <= high) {
            queue.offer((long)d);
        }
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num >= low && num <= high) {
            result.add((int)num);
        }
        if (num > high) {
            continue;
        }
        int lastDigit = (int)(num % 10);
        if (lastDigit > 0) {
            long next = num * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        if (lastDigit < 9) {
            long next = num * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n <= 0) return 0;
    long count = 0;
    long factor = 1;
    while (n / factor != 0) {
        long lower = n % factor;
        long cur = (n / factor) % 10;
        long higher = n / (factor * 10);
        count += higher * factor;
        if (cur == 1) {
            count += lower + 1;
        } else if (cur > 1) {
            count += factor;
        }
        factor *= 10;
    }
    return (int) count;
}

